<?php
session_start();
require '../../includes/conexao.php';
require '../../includes/verificar_sessao.php';
verificar_perfil('Professor');
$id_professor=$_SESSION['id_usuario'];
$id_turma=intval($_GET['turma']??$_POST['turma']??0);
$id_disciplina=intval($_GET['disciplina']??$_POST['disciplina']??0);
$turmas=[];
$stmt=$conexao->prepare('SELECT DISTINCT t.id_turma,t.nome FROM turma t JOIN turma_disciplina td ON td.id_turma=t.id_turma WHERE td.id_professor=? ORDER BY t.nome');
$stmt->bind_param('i',$id_professor);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$turmas[]=$row;}$stmt->close();
if($id_turma<=0&&count($turmas)===1)$id_turma=(int)$turmas[0]['id_turma'];
if($id_turma>0&&!array_filter($turmas,fn($row)=>(int)$row['id_turma']===$id_turma))$id_turma=0;
$disciplinas=[];
if($id_turma>0){$stmt=$conexao->prepare('SELECT DISTINCT d.id_disciplina,d.nome FROM disciplina d JOIN turma_disciplina td ON td.id_disciplina=d.id_disciplina WHERE td.id_turma=? AND td.id_professor=? ORDER BY d.nome');$stmt->bind_param('ii',$id_turma,$id_professor);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$disciplinas[]=$row;}$stmt->close();}
if($id_disciplina<=0&&count($disciplinas)===1)$id_disciplina=(int)$disciplinas[0]['id_disciplina'];
if($id_disciplina>0&&!array_filter($disciplinas,fn($row)=>(int)$row['id_disciplina']===$id_disciplina))$id_disciplina=0;
$alunos_freq=[];$turma_nome='';$disciplina_nome='';
if($id_turma>0&&$id_disciplina>0){$stmt=$conexao->prepare('SELECT td.id_turma_disciplina,t.nome AS turma_nome,d.nome AS disciplina_nome FROM turma_disciplina td JOIN turma t ON t.id_turma=td.id_turma JOIN disciplina d ON d.id_disciplina=td.id_disciplina WHERE td.id_turma=? AND td.id_disciplina=? AND td.id_professor=?');$stmt->bind_param('iii',$id_turma,$id_disciplina,$id_professor);$stmt->execute();$vinculo=$stmt->get_result()->fetch_assoc();$stmt->close();if($vinculo){$turma_nome=$vinculo['turma_nome'];$disciplina_nome=$vinculo['disciplina_nome'];$id_turma_disciplina=(int)$vinculo['id_turma_disciplina'];$stmt=$conexao->prepare('SELECT m.id_matricula,m.rm,u.nome,COALESCE(SUM(CASE WHEN f.presente=1 THEN 1 ELSE 0 END),0) AS presentes,COUNT(f.id_frequencia) AS total FROM matricula m JOIN usuario u ON u.id_usuario=m.id_aluno LEFT JOIN frequencia f ON f.id_matricula=m.id_matricula AND f.id_turma_disciplina=? WHERE m.id_turma=? GROUP BY m.id_matricula,m.rm,u.nome ORDER BY u.nome');$stmt->bind_param('ii',$id_turma_disciplina,$id_turma);$stmt->execute();$result=$stmt->get_result();while($row=$result->fetch_assoc()){$total=(int)$row['total'];$presentes=(int)$row['presentes'];$freq=$total>0?round($presentes/$total*100):0;$alunos_freq[]=['rm'=>$row['rm'],'nome'=>$row['nome'],'presentes'=>$presentes,'faltas'=>$total-$presentes,'total'=>$total,'frequencia'=>$freq,'situacao'=>$freq<75?'Risco':($freq<90?'Atenção':'Regular'),'classe'=>$freq<75?'vermelho':($freq<90?'amarelo':'verde')];}$stmt->close();}}
?><!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Professor | Presença dos alunos — Instituto Atlas</title><style>@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap');*{box-sizing:border-box}body{margin:0;background:#f7f8fc;color:#202338;font-family:Inter,Arial,sans-serif}.atlas-main{max-width:1320px;margin:0 auto;padding:36px 60px 76px}.eyebrow{font-size:11px;font-weight:800;letter-spacing:.15em;color:#777d93;text-transform:uppercase}.head{display:flex;justify-content:space-between;align-items:flex-end;gap:20px;margin-bottom:30px}.head h1{font-size:38px;letter-spacing:-.055em;margin:13px 0 8px;font-weight:800}.head h1 span{color:#6664df}.sub{color:#777d93;font-size:14px;line-height:1.6;margin:0}.tag{border:1px solid #e7e9f1;background:#fff;border-radius:30px;padding:10px 15px;font-size:12px;color:#6664df;font-weight:700}.box{background:#fff;border:1px solid #e7e9f1;border-radius:17px;padding:28px 30px;margin-bottom:20px;box-shadow:0 7px 22px rgba(29,32,63,.025)}.box h2{font-size:17px;letter-spacing:-.03em;margin:0 0 20px}.muted{color:#777d93;font-size:13px}.filters{display:flex;gap:16px;align-items:end;flex-wrap:wrap}.field{flex:1;min-width:180px}.field label,.form-label{display:block;color:#777d93;font-size:12px;font-weight:700;margin-bottom:9px}select,input,textarea{font:inherit;font-size:13px;border:1px solid #e1e4ef;background:#fafbfe;color:#292d45;border-radius:10px;padding:12px 13px;width:100%;outline:none}select:focus,input:focus,textarea:focus{border-color:#6664df;box-shadow:0 0 0 3px #6664df18}.readonly{display:flex;align-items:center;min-height:43px;padding:10px 13px;background:#fafbfe;border:1px solid #e7e9f1;border-radius:10px;font-size:13px;font-weight:700}.btn{border:0;border-radius:10px;background:#6664df;color:white;padding:13px 20px;font:inherit;font-size:12px;font-weight:800;cursor:pointer;white-space:nowrap}.btn:hover{background:#5552c9}.table-wrap{overflow-x:auto}table{width:100%;border-collapse:collapse;font-size:13px}th{text-align:left;font-size:10px;letter-spacing:.08em;text-transform:uppercase;color:#858aa0;background:#fafbfe;padding:15px 13px;white-space:nowrap}td{padding:15px 13px;border-bottom:1px solid #eef0f6;color:#353950}tbody tr:last-child td{border-bottom:0}.badge{display:inline-block;padding:7px 11px;border-radius:100px;font-size:11px;font-weight:800}.verde{background:#e8f8ef;color:#207a4a}.amarelo{background:#fff4df;color:#946000}.vermelho{background:#ffe9ec;color:#b3334c}.empty{padding:24px;border:1px dashed #dfe2ef;border-radius:12px;color:#777d93;font-size:13px;text-align:center}.section-head{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:20px}.section-head h2{margin:0}.hint{font-size:12px;color:#858aa0}@media(max-width:1100px){.atlas-main{padding:32px 30px 65px}}@media(max-width:700px){.atlas-main{padding:28px 18px 50px}.head h1{font-size:31px}.tag{display:none}.box{padding:22px 18px}.filters{display:block}.field{margin-bottom:14px}.btn{width:100%}}</style></head><body><?php include '../../includes/menu_professor.php'; ?><main class="atlas-main"><header class="head"><div><div class="eyebrow">Instituto Atlas &nbsp;/&nbsp; Portal do professor</div><h1>Presença dos alunos<span>.</span></h1><p class="sub">Acompanhe a frequência e os registros de cada turma.</p></div><span class="tag">Área do professor</span></header><section class="box"><div class="section-head"><h2>Selecionar turma e disciplina</h2><span class="hint">Consulte os registros por disciplina</span></div><form method="GET" class="filters"><div class="field"><label for="turma">Turma</label><?php if(count($turmas)===1):?><input type="hidden" name="turma" value="<?php echo $id_turma;?>"><div class="readonly"><?php echo htmlspecialchars($turmas[0]['nome']);?></div><?php else:?><select id="turma" name="turma" onchange="this.form.submit()"><option value="">Selecione uma turma</option><?php foreach($turmas as $turma):?><option value="<?php echo $turma['id_turma'];?>" <?php echo $id_turma==$turma['id_turma']?'selected':'';?>><?php echo htmlspecialchars($turma['nome']);?></option><?php endforeach;?></select><?php endif;?></div><div class="field"><label for="disciplina">Disciplina</label><?php if(count($disciplinas)===1):?><input type="hidden" name="disciplina" value="<?php echo $id_disciplina;?>"><div class="readonly"><?php echo htmlspecialchars($disciplinas[0]['nome']);?></div><?php else:?><select id="disciplina" name="disciplina"><option value="">Selecione uma disciplina</option><?php foreach($disciplinas as $disc):?><option value="<?php echo $disc['id_disciplina'];?>" <?php echo $id_disciplina==$disc['id_disciplina']?'selected':'';?>><?php echo htmlspecialchars($disc['nome']);?></option><?php endforeach;?></select><?php endif;?></div><button class="btn" type="submit">Consultar frequência</button></form></section><?php if($id_turma>0&&$id_disciplina>0):?><section class="box"><div class="section-head"><h2>Frequência · <?php echo htmlspecialchars($turma_nome.' · '.$disciplina_nome);?></h2><span class="hint"><?php echo count($alunos_freq);?> alunos</span></div><?php if($alunos_freq):?><div class="table-wrap"><table><thead><tr><th>RM</th><th>Aluno</th><th>Presenças</th><th>Faltas</th><th>Total</th><th>Frequência</th><th>Situação</th></tr></thead><tbody><?php foreach($alunos_freq as $aluno):?><tr><td><?php echo htmlspecialchars($aluno['rm']);?></td><td><strong><?php echo htmlspecialchars($aluno['nome']);?></strong></td><td><?php echo $aluno['presentes'];?></td><td><?php echo $aluno['faltas'];?></td><td><?php echo $aluno['total'];?></td><td><strong><?php echo $aluno['frequencia'];?>%</strong></td><td><span class="badge <?php echo $aluno['classe'];?>"><?php echo $aluno['situacao'];?></span></td></tr><?php endforeach;?></tbody></table></div><?php else:?><div class="empty">Nenhum aluno ou registro de frequência encontrado.</div><?php endif;?></section><?php else:?><section class="box"><div class="empty">Selecione uma turma e uma disciplina para visualizar a frequência.</div></section><?php endif;?></main></body></html>